"""Serialize the authored governance-body context design."""
import json
import re
from pathlib import Path
RUN=Path(__file__).resolve().parent
def refs(*ns): return [f'SRC-{n:03d}' for n in ns]

def build():
    rows=[
      ('The Organization Ontology','W3C','https://www.w3.org/TR/vocab-org/','Recommendation; dated pin pending','ontology','Selected Organization, Membership, Post and memberDuring; authority nuances explicitly require extensions.'),
      ('G20/OECD Principles of Corporate Governance: board responsibilities','OECD','https://www.oecd.org/en/publications/g20-oecd-principles-of-corporate-governance-2023_ed750b30-en/full-report/component-8.html','11 September 2023, V.E.2 selected','first-party-doc','Committee mandate, composition, procedure and retained accountability; not universal law. Direct HEAD unavailable, web text inspected.'),
      ('Charity meetings CC48','Charity Commission for England and Wales','https://www.gov.uk/government/publications/charities-and-meetings-cc48/charities-and-meetings','Updated 19 July 2024','public-authority','Selected governing-document, quorum, voting and minutes clauses; England/Wales profile, no universal numeric defaults.'),
      ('Charter of the Internet Architecture Board','IETF/IAB','https://www.rfc-editor.org/rfc/rfc2850','RFC2850 May 2000, updated by RFC9283','standard','Selected officers, participant classes, decision-taking and confidentiality; historical charter must be read with updates.'),
      ('IAB Charter Update for RFC Editor Model','IETF','https://www.rfc-editor.org/rfc/rfc9283','RFC9283 June 2022','standard','Selected changes to RFC2850 mandate and liaison provisions; demonstrates versioned authority, not a universal body model.'),
      ('PROV-O: The PROV Ontology','W3C','https://www.w3.org/TR/prov-o/','Recommendation; exact dated pin pending','ontology','Qualified activity/agent/role attribution, not proof of authority or decision truth.'),
      ('Date and Time on the Internet: Timestamps','IETF','https://www.rfc-editor.org/rfc/rfc3339','RFC3339 July 2002','standard','Selected seconds and offset grammar; date-only effects remain separate. Direct RFC HEAD probes unavailable, web text inspected.')]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=2 if k=='first-party-doc' else 1,accessed_at='2026-09-09T21:50:15Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['body-constitution','body-mandate','body-membership','body-officers','body-recusal','body-procedure','body-sessions','body-outcomes','body-evaluation','body-succession','body-stewardship','body-mapping']
    citations=[refs(1,2,4),refs(2,4,5),refs(1,3,4),refs(1,3,4),refs(2,3,4),refs(3,4),refs(2,3,4),refs(3,4,6),refs(2,4),refs(1,2,5,6,7),refs(3,4,6,7),refs(1,2,3,4,5,6,7)]
    kinds=[['identity','authority','classification'],['definition','authority','relationship'],['composition','provenance','exception'],['ownership','authority','exception'],['access','evidence','constraint'],['process','constraint','decision'],['relationship','provenance','access'],['evidence','state','process'],['requirement','measurement','decision'],['lifecycle','event','ownership'],['ownership','access','retention'],['interoperability','quality','validation']]
    bundles=[]; n=0
    for group in re.split(r'(?m)^## ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qs,answers=body.split('Answer groups:',1)
            questions=re.findall(r'(?m)^\d\. (.+\?)$',qs); groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answers)
            assert len(questions)==len(groups)==3
            lid=ids[n]; sr=citations[n]
            desc='Constituted-body '+name.lower()+' context qualified by governing instrument, time and evidence; not an executable legal-validity judgment.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed answer fields: '+members+'. Unknowns must be explicit; source and rule version required where relevant. Nested executable schemas remain deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-artifact',name=name+' evidence artifact',description='Revisioned assertion with minimal authorized references; confidential papers and unnecessary member details remain in protected masters.',media_or_form=['text/markdown','application/json','application/yaml','external reference'],serial=True,identity_strategy='Master-qualified stable ID, otherwise Dimension UUID; immutable revision and digest are separate, timestamp alone is not unique.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding])); n+=1
        assert len(layers)==2
        bundles.append(dict(id='body-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Governance-body '+title.lower()+'.',rationale='Pairs body-owned context records; meetings, decisions, persons and operational actions retain their own masters.',source_refs=sorted(set(s for layer in layers for s in layer['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-org-018',model_id='WM-ORG-018',name='Governance Body / Committee',entry_kind='entity',purpose='Describe a constituted collective body through mandate, membership and decision-authority context.',scope_statement='An enduring body that persists across sessions and membership turnover; distinguish its constitution, seats, holders, procedure and references to decisions. Not a meeting, legal entity by default or legal-validity engine.',in_scope=['Body identity, establishment, mandate and delegation limits','Seats, terms, officers, participation and rule-specific decision procedure','Decision evidence references, reporting, renewal, dissolution and governed records'],out_of_scope=['Underlying person or organization identity and full meeting/decision payloads','Appointing people, casting votes, convening meetings or executing resolutions','Universal quorum, legal validity, retention periods or unrestricted delegated power'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=c) for a,b,c in [('Organization or unit','A constituted body can be situated in an organization without automatically being a separate legal entity.',refs(1,2)),('Meeting session','Body identity persists across meetings; candidate meeting relationship is not approved composition.',refs(3,4)),('Member and post','Seat, membership term and person are distinct; membership does not automatically confer voting or access rights.',refs(1,3,4)),('Decision and operational action','Records reference outcomes and their basis without adopting, validating legally or executing them.',refs(2,3,4))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Declare body-record owner and accountable custodian.','Identify constitution, membership, rule, meeting and decision masters.','Bind delegation, confidentiality, correction and retention policies.'],namespace_guidance='Body ID is master-qualified and persists across membership turnover; never identify the body only by a chair name or meeting date.',registry_links=['Governance body registry','Constitution, role and membership references','Meeting and decision registries','Policy and revision registries']),
      canon_and_patch=dict(canonicalization_rules=['Keep instrument version, valid term and decision category explicit.','Separate body, seat, holder, meeting, outcome and execution authority.'],patch_rules=['Add namespaced governance profiles pinned to base version/digest.','Append expected-head corrections preserving objections, rule history and competing assertions.'],compatibility_rules=['Changes to quorum population, threshold or mandate require migration and loss reporting.','Do not apply a new rule retroactively or map attendance to voting eligibility.']),
      artifact_rules=dict(identity_priority=['Authoritative master-qualified ID','Governed issuer-qualified URI','Dimension-issued UUID'],timestamp_rule='RFC 3339 with seconds and explicit offset or Z for recording/observation instants; preserve uncertain effective dates separately.',serial_naming_rule='Body record-kind prefix plus escaped stable ID and revision; avoid private member names in paths.',integrity_rule='Check exact-byte digest and source revision; integrity does not prove a valid appointment or decision.'),
      policies=['Never infer binding authority from committee name, chair role or membership alone.','Use the actual governing rule for eligibility, recusal, quorum and decision categories; no universal arithmetic defaults.','Retain dissent, draft/approved/contested record states and versioned mandate changes.','Minimize personal and confidential materials; record maintenance does not authorize votes, appointments or publication.'],
      crud=dict(read=['Read owner policy, body mandate, instrument version, valid terms and assurance first.'],create=['Record authorized constitution or membership assertions with evidence and unknowns, not invented authority.'],update=['Append rule or term evidence under expected-head and scope checks; retain prior validity and contested records.'],delete=['Apply justified retention and correction/tombstone rules; local removal does not dissolve a body or cancel a decision.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Sets delegated scope and purpose.'),('Body-record steward','Maintains constitution and role-source references.'),('Contributor','Records authorized minimal evidence.'),('Reviewer','Checks scope, rule-version and disputed appointment/outcome assertions.'),('Custodian','Protects papers and enforces retention and revision integrity.')]],
      access=dict(default_rule='Deny unless field- and purpose-specific access is delegated; record access is not membership or a vote.',scopes=['bundle','layer','finding','artifact'],exceptions=['Only explicit time-limited exceptions naming approving authority, purpose and fields.'],audit_requirements=['Log actor, record, revision, authorized operation and disclosure decision without confidential payloads or credentials.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension authority and confidentiality policy','Pinned body specification and constitution','Mandate, membership terms, governing rules and evidence','Safe record operations, validation, extensions and lifecycle']))
    frows=[
      ('resolve-body','Resolve constituted body','Identify the body independently of its current holders and meetings.',['Qualified ID or candidates','Organizational scope'],['Body reference or ambiguity'],['Read permission','Identity scope checked'],['Read-only lookup, no constitution or appointment'],refs(1,2)),
      ('record-mandate','Record mandate evidence','Append an attributed constitution or delegated-power assertion.',['Instrument reference','Scope and valid time','Expected head'],['Revision or contested assertion'],['Write delegation','Source version known or explicit unknown'],['Local record only; no new governing authority granted'],refs(2,4,5,6)),
      ('record-membership','Record membership assertion','Link a party, seat and term from an authoritative record.',['Appointment reference','Party/seat refs','Term and expected revision'],['Membership assertion or unresolved evidence'],['Write scope','No attendance-only appointment inference'],['No appointment, removal, access grant or vote'],refs(1,3,4,6)),
      ('link-body-evidence','Link rule and decision evidence','Connect governed session and outcome references.',['Meeting/decision refs','Rule version','Expected revision'],['Traceable links or ambiguity'],['Authorized reference access','Decision category retained'],['No legal validity declaration, vote or outcome execution'],refs(3,4,6)),
      ('record-body-change','Record lifecycle review','Preserve evidence of review, renewal or dissolution decisions.',['Decision/transition refs','Time and handover refs','Expected head'],['Successor record with outstanding matters'],['Competent authority reference','Write permission'],['No dissolution execution or automatic transfer of powers'],refs(1,2,5,6,7)),
      ('export-body','Export authorized projection','Map minimized body context without losing authority distinctions.',['Allowed fields','Pinned target profile','Loss rules'],['Projection or refusal'],['Disclosure authority','Term and rule distinctions checked'],['No external release without authority; unresolved semantics yield warning/refusal'],refs(1,2,3,4))]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in frows]
    composition=[dict(target=t,relation=r,purpose=p,required=False,source_refs=s) for t,r,p,s in [('WM-ORG-003','REFERENCE','Proposed containing organizational context, not automatic legal identity.',refs(1,2)),('WM-ACT-025','REFERENCE','Candidate meeting-session relationship; ledger CONTAINS is not yet approved, use non-owning reference only.',refs(3,4)),(rows[0][2],'ALIGN','Candidate membership/post mapping; ORG alone does not express full governance authority.',refs(1)),(rows[5][2],'ALIGN','Candidate assertion-attribution vocabulary, not proof of valid authority.',refs(6))]]
    dims=[('identity','Enduring master-qualified body.'),('classification','Constituted governing, advisory or temporary body.'),('direct properties','Mandate, composition, terms and rule references.'),('recognition','Establishment and appointment evidence, not names alone.'),('capabilities','Six bounded context-record functions.'),('lifecycle','Review, renewal, succession and dissolution references.'),('relationships','Organization, seat, member, session and decision remain separate.'),('temporal','Valid terms and observation/recording precision separated.'),('provenance','Instrument and evidence versions preserve attribution.'),('ownership','Record steward distinct from governing authority.'),('access','Confidential fields and purpose-specific authorization.'),('retention','Policy-specific preservation, objections and correction.'),('interoperability','Loss-aware ORG/profile mapping, no authority inference.')]
    coverage=dict(claim='Bounded governance-body context contract; not exhaustive legal governance, an executable quorum engine or independent review.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='validation',status='gap',notes='Research structure validated separately; nested schemas and profile-specific quorum/recusal/authority fixtures not implemented.'),dict(dimension='Physical properties',status='not-applicable',notes='Constituted body is abstract; geometry belongs to sites and sessions.')],known_omissions=['Claude and Grok each timed out once; Codex-only reviewable-draft lacks independent review.','Selected-source clauses only; dated pins, full licensing and jurisdiction/profile applicability remain pending.','OECD and RFC direct HEAD probes unavailable despite readable web text; transport limitation remains visible.','No executable nested schema, quorum calculator, appointment verifier or decision-validity/round-trip fixtures.','Candidate meeting composition and broader legal/body profiles remain unapproved.'],conflicts=[],regional_assumptions=['CC48 applies to England and Wales charities, OECD to corporate governance guidance, and IAB charter rules only to that body; no numeric rule is universalized.'],adversarial_checks=['Observer attendance does not confer vote or quorum eligibility.','Recusal effects require the exact applicable rule.','Abstention, dissent and absence are not interchangeable.','Draft minutes are not approved and objections survive corrections.','Rule amendments cannot silently alter prior decisions.','Dissolution does not automatically transfer powers.','Record access does not confer membership.','Chair authority does not imply unrestricted substantive power.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
